const TRIAGE_LABELS = [
  'triage:pending', 'triage:in-progress', 'triage:needs-info',
  'triage:needs-reproduction', 'triage:ready-for-review', 'triage:complete',
  'triage:stalled', 'triage:ping', 'triage:tests-needed',
];

const TEAM_LABELS = [
  'team:nodes', 'team:ai', 'team:api', 'team:iam', 'team:chat', 'team:design',
  'team:qa-dx', 'team:lifecycle', 'team:relay', 'team:identity', 'team:cats',
  'team:payday', 'team:adore', 'team:ins', 'team:instance-ai',
];

const CLOSED_LABELS = [
  'closed:duplicate', 'closed:cant-reproduce', 'closed:working-as-expected',
  'closed:support-issue', 'closed:incomplete-template',
  'closed:enhancement/feature', 'closed:info', 'closed:non-english',
  'closed:requested',
];

const ALL_FILTER_LABELS = [...TRIAGE_LABELS, ...TEAM_LABELS, ...CLOSED_LABELS];

// Spec section 8 headline: the rejection reasons which say the issue should
// never have been filed as a bug at all. A subset of CLOSED_LABELS. An issue
// carrying two of them is counted once.
const SHOULD_NOT_HAVE_BEEN_FILED = [
  'closed:incomplete-template', 'closed:support-issue', 'closed:non-english',
];

// Retained deliberately: these matched ZERO issues in the measured population
// because they never co-occur with the 33 filter labels. They cost nothing and
// n8n's labelling may change. Do not delete them assuming they are broken.
const ADHOC_COMPONENT_LABELS = [
  'core', 'ui', 'dx', 'deployment', 'performance', 'security',
];



const namesOf = issue => (issue.labels?.nodes ?? []).map(l => l.name);

function segmentOf(issue) {
  return namesOf(issue).some(n => n.startsWith('closed:')) ? 'rejected' : 'accepted';
}

function packageOf(paths) {
  const counts = new Map();
  for (const path of paths) {
    if (!path.startsWith('packages/')) continue;
    const seg = path.split('/');
    // Scoped packages need three segments: packages/@n8n/db, not packages/@n8n.
    const depth = seg[1]?.startsWith('@') ? 3 : 2;
    if (seg.length < depth) continue;
    const key = seg.slice(0, depth).join('/');
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  if (counts.size === 0) return null;
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0][0];
}

function componentOf(issue) {
  if (segmentOf(issue) === 'rejected') return null;

  const names = namesOf(issue);

  const team = names.find(n => n.startsWith('team:'));
  if (team) return team.slice('team:'.length);

  if (names.some(n => n.startsWith('node/'))) return 'nodes';

  const adhoc = names.find(n => ADHOC_COMPONENT_LABELS.includes(n));
  if (adhoc) return adhoc;

  // Only MERGED pull requests are evidence of where the fix landed.
  const paths = (issue.closedByPullRequestsReferences?.nodes ?? [])
    .filter(pr => pr.mergedAt != null)
    .flatMap(pr => (pr.files?.nodes ?? []).map(f => f.path));

  return packageOf(paths) ?? 'unclassified';
}


const DAY_MS = 86_400_000;
const days = (from, to) =>
  from && to ? (Date.parse(to) - Date.parse(from)) / DAY_MS : null;

function median(nums) {
  if (nums.length === 0) return null;
  const s = [...nums].sort((a, b) => a - b);
  const mid = s.length >> 1;
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

function p90(nums) {
  if (nums.length === 0) return null;
  const s = [...nums].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.ceil(s.length * 0.9) - 1)];
}

function leadTimes(issue) {
  // Only merged PRs count. 55% of linked PRs were closed without merging.
  const merged = (issue.closedByPullRequestsReferences?.nodes ?? [])
    .filter(pr => pr.mergedAt != null)
    .sort((a, b) => Date.parse(a.mergedAt) - Date.parse(b.mergedAt));
  const first = merged[0] ?? null;

  return {
    closeDays: days(issue.createdAt, issue.closedAt),
    fixDays: first ? days(issue.createdAt, first.mergedAt) : null,
    prDays: first ? days(first.createdAt, first.mergedAt) : null,
  };
}




const bump = (obj, key) => { obj[key] = (obj[key] ?? 0) + 1; };
const summarise = xs => ({ median: median(xs), p90: p90(xs), n: xs.length });

// ---------------------------------------------------------------------------
// TWO DENOMINATORS, DELIBERATELY. DO NOT "SIMPLIFY" THIS INTO ONE.
// ---------------------------------------------------------------------------
//
// The store keeps full history. This rollup reports over two different
// populations, and which measure gets which population is load-bearing:
//
//   WINDOWED by createdAt >= now - windowDays:
//     segments, rejectionReasons, components, componentCoverage,
//     triageStates, triagedIssues, byMonth, headline.
//     These describe INTAKE. "What is arriving, and what do we do with it"
//     is a question about the recent past; answering it over five years of
//     history buries a change in triage practice under the back catalogue.
//
//   NOT WINDOWED — all history, always:
//     leadTimes.close, leadTimes.fix, leadTimes.pr.
//     Windowing a duration by the date the issue was CREATED truncates the
//     distribution: a slow issue created inside the window has not finished
//     yet, and a slow issue that did finish was created before it. Only the
//     fast half survives, so the median collapses.
//
//     Measured on the real 5,464-record store: median fix lead time is
//     25.3 days over all history, but 12.7 days if the population is windowed
//     by creation date. That is a 2x UNDERSTATEMENT, and it is pure
//     truncation bias, not a real improvement. The tail is the whole story of
//     a lead-time distribution; a window amputates it.
//
// `total` therefore stays the FULL population while `window.population` gives
// the windowed one, so every table in the report can print the denominator it
// was actually computed over. See tests/rollup.test.js, "lead times cover all
// history, never the window".

function rollup(issues, { windowDays = 180, now = new Date() } = {}) {
  const nowMs = now instanceof Date ? now.getTime() : Date.parse(now);
  const sinceMs = nowMs - windowDays * DAY_MS;

  const segments = { accepted: 0, rejected: 0 };
  const rejectionReasons = {}, components = {}, triageStates = {}, byMonth = {};
  const close = [], fix = [], pr = [];
  let windowPopulation = 0;
  let shouldNotHaveBeenFiled = 0, shouldNotHaveBeenFiledAllTime = 0;
  let triagedIssues = 0;

  for (const issue of issues) {
    // --- All history: lead times and the all-time headline ------------------
    const lt = leadTimes(issue);
    if (lt.closeDays != null) close.push(lt.closeDays);
    if (lt.fixDays != null) fix.push(lt.fixDays);
    if (lt.prDays != null) pr.push(lt.prDays);

    const names = (issue.labels?.nodes ?? []).map(l => l.name);
    // Counted once per issue, however many of the three reasons it carries.
    const neverShouldHaveBeenFiled = names.some(n => SHOULD_NOT_HAVE_BEEN_FILED.includes(n));
    if (neverShouldHaveBeenFiled) shouldNotHaveBeenFiledAllTime += 1;

    // --- The window: everything below describes intake ----------------------
    // A record with no parsable createdAt cannot be placed in time, so it
    // counts in `total` and in the lead times but never in the window.
    if (!(Date.parse(issue.createdAt) >= sinceMs)) continue;
    windowPopulation += 1;

    const segment = segmentOf(issue);
    segments[segment] += 1;

    // triageStates counts LABELS; triagedIssues counts ISSUES. They are not
    // interchangeable and summing the first does NOT give the second: on the
    // real store 1,546 triage:* labels are spread across 1,309 issues, because
    // 237 issues carry more than one. Deriving the funnel denominator by
    // summing triageStates published "1546 carry a triage label ... the other
    // 3918 carry none" against a truth of 1,309 and 4,155. Use triagedIssues
    // for any per-issue denominator.
    let carriesTriageLabel = false;
    for (const n of names) {
      if (n.startsWith('closed:')) bump(rejectionReasons, n);
      if (n.startsWith('triage:')) { bump(triageStates, n); carriesTriageLabel = true; }
    }
    if (carriesTriageLabel) triagedIssues += 1;

    if (neverShouldHaveBeenFiled) shouldNotHaveBeenFiled += 1;

    if (segment === 'accepted') bump(components, componentOf(issue));

    const month = (issue.createdAt ?? '').slice(0, 7);
    if (month) {
      byMonth[month] ??= { accepted: 0, rejected: 0 };
      byMonth[month][segment] += 1;
    }
  }

  const classified = segments.accepted - (components.unclassified ?? 0);

  return {
    total: issues.length,
    window: {
      since: new Date(sinceMs).toISOString(),
      days: windowDays,
      population: windowPopulation,
    },
    segments,
    headline: {
      shouldNotHaveBeenFiled,
      shareOfPopulation: windowPopulation === 0 ? 0 : shouldNotHaveBeenFiled / windowPopulation,
      allTime: {
        shouldNotHaveBeenFiled: shouldNotHaveBeenFiledAllTime,
        shareOfPopulation: issues.length === 0 ? 0 : shouldNotHaveBeenFiledAllTime / issues.length,
      },
    },
    rejectionReasons,
    components,
    componentCoverage: segments.accepted === 0 ? 0 : classified / segments.accepted,
    triageStates,
    triagedIssues,
    leadTimes: { close: summarise(close), fix: summarise(fix), pr: summarise(pr) },
    byMonth,
  };
}


const pct = (n, d) => d === 0 ? '0%' : `${Math.round(n / d * 100)}%`;
const num = v => v == null ? '—' : (Math.round(v * 10) / 10).toString();

const table = (header, rows) =>
  [`| ${header.join(' | ')} |`,
   `|${header.map(() => '---').join('|')}|`,
   ...rows.map(r => `| ${r.join(' | ')} |`)].join('\n');

const sortedEntries = obj => Object.entries(obj).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

function reportPath(date) {
  return `reports/${date.toISOString().slice(0, 10)}-triage.md`;
}

// The accepted:rejected ratio, expressed as accepted issues per rejected issue.
// Undefined when nothing was rejected, which prints as an em dash.
const ratio = (a, b) => b === 0 ? '—' : (a / b).toFixed(2);

// This report publishes TWO denominators and must never let a reader guess
// which one a table used — see the comment at the top of src/lib/rollup.js for
// why the split exists. Every windowed table repeats `windowLine` verbatim;
// the lead-time table says plainly that it is not windowed. Do not collapse
// these into a single note at the top: a table read on its own would then
// carry no denominator at all.
function renderReport(r, { generatedAt }) {
  const { total, segments: s, window: w } = r;
  const lt = r.leadTimes;
  const h = r.headline;
  // NOT Object.values(r.triageStates).reduce(...) — that sums LABELS, and an
  // issue may carry more than one triage:* label (237 of 1,309 do on the real
  // store). The funnel denominator sentence is about ISSUES, so it must use
  // the per-issue count. See src/lib/rollup.js.
  const triaged = r.triagedIssues;
  const since = w.since.slice(0, 10);
  const windowLine = `Window: the ${w.days} days since ${since}.`;

  return `# n8n triage report — ${generatedAt.slice(0, 10)}

Population: **${total}** triaged issues from \`n8n-io/n8n\`.
Generated ${generatedAt}.

**This report uses two denominators, deliberately.** The intake sections below cover the **${w.days} days since ${since}** — **${w.population}** of the ${total} triaged issues in the store, by issue creation date. The **lead times cover all history**, all ${total} issues: windowing a duration by the date the issue was created truncates the slow tail and understates the median by about 2x.

## Headline

- In the ${w.days} days since ${since}: **${s.accepted} accepted** to **${s.rejected} rejected** — a ratio of **${ratio(s.accepted, s.rejected)}** accepted issues per rejected issue, out of ${w.population} issues created in the window.
- **${h.shouldNotHaveBeenFiled}** ${h.shouldNotHaveBeenFiled === 1 ? 'issue' : 'issues'} (**${pct(h.shouldNotHaveBeenFiled, w.population)}** of ${w.population}) should never have been filed as a bug. Over all history the figure is **${h.allTime.shouldNotHaveBeenFiled}** of ${total} (**${pct(h.allTime.shouldNotHaveBeenFiled, total)}**) — the rate barely moves between the window and the full store, which is itself the finding. n8n closed them as \`closed:incomplete-template\`, \`closed:support-issue\` or \`closed:non-english\`. An issue carrying more than one of those reasons is counted once.

## Intake and outcome

${windowLine}

${table(['Segment', 'Issues', 'Share'], [
  ['Accepted', s.accepted, pct(s.accepted, w.population)],
  ['Rejected at triage', s.rejected, pct(s.rejected, w.population)],
])}

Denominator: the **${w.population}** issues created in the window.

## Rejection reasons

${windowLine}

${table(['Reason', 'Issues', 'Share of rejected'],
  sortedEntries(r.rejectionReasons).map(([k, v]) => [k, v, pct(v, s.rejected)]))}

Denominator: the **${s.rejected}** issues rejected in the window. An issue may carry more than one reason, so the counts need not sum to ${s.rejected} and the shares need not sum to 100%.

## Component

${windowLine} Accepted issues only. Component coverage: **${pct(r.componentCoverage * s.accepted, s.accepted)}** of ${s.accepted} accepted issues.

${table(['Component', 'Issues'], sortedEntries(r.components))}

## Triage funnel

${windowLine}

${table(['State', 'Issues', 'Share'],
  sortedEntries(r.triageStates).map(([k, v]) => [k, v, pct(v, w.population)]))}

Denominator: the **${w.population}** issues created in the window. ${triaged} carry a \`triage:*\` label and appear above; the other ${w.population - triaged} carry none and appear in no row. The rows count labels, not issues: an issue carrying two \`triage:*\` labels appears in two rows, so the counts need not sum to ${triaged} and the shares need not sum to 100%.

## Lead times

**Not windowed — all ${total} issues, all history.** A lead time windowed by creation date is truncated at both ends: a slow issue created inside the window has usually not finished yet, and a slow issue that has finished was created before it. On the real store that halves the reported median. The tail is the story, so these three rows always cover the whole population.

Reported as median and p90. Means are omitted deliberately: the distribution has a long tail and an average would be meaningless.

${table(['Measure', 'Median (days)', 'p90 (days)', 'n'], [
  ['Issue opened → closed', num(lt.close.median), num(lt.close.p90), lt.close.n],
  ['Issue opened → fix merged', num(lt.fix.median), num(lt.fix.p90), lt.fix.n],
  ['Fix PR opened → merged', num(lt.pr.median), num(lt.pr.p90), lt.pr.n],
])}

## Monthly intake

${windowLine}

${table(['Month', 'Accepted', 'Rejected', 'Total', 'Share'],
  Object.entries(r.byMonth).sort(([a], [b]) => a.localeCompare(b))
    .map(([m, v]) => [m, v.accepted, v.rejected, v.accepted + v.rejected, pct(v.accepted + v.rejected, w.population)]))}

Denominator: the **${w.population}** issues created in the window, keyed by the month the issue was opened.

## Coverage and caveats

- This measures **intake and triage, not delivery.** n8n moves accepted issues into **Linear**, at which point GitHub stops being the system of record. Do not read this as engineering throughput.
- The intake sections and the lead times use **different populations on purpose.** Intake is a question about the recent past, so it is windowed; a lead time windowed by creation date is truncated, so it is not. Comparing a windowed count against an all-time one is a mistake the section notes exist to prevent.
- Only issues carrying one of 33 \`triage:*\`, \`team:*\` or \`closed:*\` labels are included. Unlabelled community issues are out of scope.
- \`unclassified\` counts accepted issues with no team label and no merged fix PR to derive a component from. It is reported, not hidden.
- Fix lead time is computed only where a linked PR was actually **merged**. Linked-but-unmerged PRs are excluded.
`;
}


function parseStore(text) {
  const map = new Map();
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const issue = JSON.parse(trimmed);
    map.set(issue.number, issue);
  }
  return map;
}

function serialiseStore(map) {
  return [...map.values()]
    .sort((a, b) => a.number - b.number)
    .map(i => JSON.stringify(i))
    .join('\n') + '\n';
}

function upsert(map, issues) {
  for (const issue of issues) map.set(issue.number, issue);
  return map;
}

function watermarkOf(map) {
  let max = null;
  for (const issue of map.values()) {
    if (issue.updatedAt && (max === null || issue.updatedAt > max)) max = issue.updatedAt;
  }
  return max;
}


const MIN_STORE_FRACTION = 0.9;

function assertStoreIsIntact(store, state = {}) {
  if (store.size === 0) {
    throw new Error(
      'refusing to write: the store read back EMPTY. GitHub\'s Contents API returns HTTP 200 ' +
      'with an empty content field for files over 1 MB — read issues.ndjson with ' +
      'Accept: application/vnd.github.raw. Writing now would destroy the store.'
    );
  }
  const expected = typeof state.records === 'number' ? state.records : null;
  if (expected !== null && store.size < expected * MIN_STORE_FRACTION) {
    throw new Error(
      `refusing to write: the store read back ${store.size} record(s) but state.json records ` +
      `${expected}. That is below ${MIN_STORE_FRACTION * 100}% of the expected count, so the read ` +
      'was short. Writing now would shrink the store.'
    );
  }
}

function buildReportPayload(storeText, generatedAtISO) {
  const store = parseStore(storeText);
  // The report does not write the store, but publishing "Population: 0" from
  // a truncated read is its own kind of silent wrong answer.
  assertStoreIsIntact(store);
  const issues = [...store.values()];
  // `now` must be the report's own timestamp, not wall-clock time: the 6-month
  // intake window is computed from it, and leaving it to Date.now() makes the
  // report non-deterministic and untestable.
  const r = rollup(issues, { now: new Date(generatedAtISO) });
  const content = renderReport(r, { generatedAt: generatedAtISO });
  const path = reportPath(new Date(generatedAtISO));
  return { path, content };
}

// --- n8n driver ---------------------------------------------------------
// CRITICAL MEMORY CONSTRAINT (spec section 5): this node must receive the
// store as ONE item containing text and must return ONE item containing the
// rendered report. Do NOT change this to emit one item per issue. n8n holds
// every node's output array in memory for the whole execution; the store
// holds 5,464+ issues, and one item per issue is the exact out-of-memory
// failure this project exists to avoid. buildReportPayload() folds the whole
// store into a single object -- keep it that way.
//
// The upstream node reads with Accept: application/vnd.github.raw, so the
// store arrives as text on $json.data, NOT as base64 on $json.content. The
// Contents API's JSON envelope truncates files over 1 MB to an empty string.
const item = $input.first();
const storeText = item.json.data;
const generatedAt = new Date().toISOString();

// generatedAt is threaded all the way into rollup(), so the report's 6-month
// intake window is anchored to the report timestamp printed in its header
// rather than to wall-clock time read somewhere deeper.
const payload = buildReportPayload(storeText, generatedAt);

return [{
  json: {
    path: payload.path,
    content: Buffer.from(payload.content, 'utf8').toString('base64'),
  },
}];
